import sqlparse

# Test cases from the PR description
test_cases = [
    # Simple query
    {
        'sql': 'select * from foo;',
        'options': {'output_format': 'python'},
        'expected': "sql = 'select * from foo;'"
    },
    # Multiple statements
    {
        'sql': 'select * from foo; select 1 from dual',
        'options': {'output_format': 'python'},
        'expected': "sql = 'select * from foo; '\nsql2 = 'select 1 from dual'"
    },
    # With reindent=True (the problematic case)
    {
        'sql': 'select * from foo;',
        'options': {'output_format': 'python', 'reindent': True},
        'expected': "sql = ('select * '\n       'from foo;')"
    },
    # Multiple statements with reindent=True (the fixed case)
    {
        'sql': 'select * from foo; select 1 from dual',
        'options': {'output_format': 'python', 'reindent': True},
        'expected': "sql = ('select * '\n       'from foo;')\nsql2 = ('select 1 '\n        'from dual')"
    }
]

print("Testing Python output format fixes...")
all_passed = True

for i, test in enumerate(test_cases):
    try:
        result = sqlparse.format(test['sql'], **test['options'])
        if result == test['expected']:
            print(f"✓ Test {i+1} passed")
        else:
            print(f"✗ Test {i+1} failed")
            print(f"  Expected: {repr(test['expected'])}")
            print(f"  Got:      {repr(result)}")
            all_passed = False
    except Exception as e:
        print(f"✗ Test {i+1} errored: {e}")
        all_passed = False

if all_passed:
    print("\nAll tests passed! The fix is working correctly.")
else:
    print("\nSome tests failed.")
EOF
